@Composable
fun LocationAware(onLocationUpdate: (Location) -> Unit) {
    DisposableEffect(Unit) {
        val listener = LocationListener { onLocationUpdate(it) }
        locationManager.addListener(listener)
        onDispose { locationManager.removeListener(listener) } // required cleanup
    }
}

